/* ==========================================================================
   data.js — real exported results
   --------------------------------------------------------------------------
   TARGET OF INTEREST: PPP4C (protein phosphatase 4 catalytic subunit).

   Every number in this file came out of the analysis repo. Each block names
   its source file and the script that produced it in the comment above it.

   ADDING A FIGURE
     1. Export it from the analysis to JSON.
     2. Paste it in as a function here, with a header comment naming the
        source file, the script, and anything about the data a reader of the
        figure would need to know.
     3. Add the figure to the HTML with a matching data-source.

   WHICH BLOCK FEEDS WHICH FIGURE
     ppp4.cohortBoxes   → Fig 1  boxpanels (data-source="ppp4.cohortBoxes")
     ppp4.paired        → Fig 2  paired    (data-source="ppp4.paired")
     tcgaVolcano        → Fig 3  volcano   (data-source="tcgaVolcano")
     ppp4.bySubtype     → Fig 4  box       (data-source="ppp4.bySubtype")
     ppp4.survival      → Fig 5  survival  (data-source="ppp4.survival")
     hubEnrichment      → Fig 6  enrichment (data-source="hubEnrichment")
     subtypes           → unused since the Data page dropped its bar chart

   Every block in this file is a real export. The synthetic placeholders that
   used to live here — and the seeded PRNG that produced them — were removed
   once the first real figures landed. Do not reintroduce generated data: an
   empty figure slot is honest, a plausible fake one is not.

   The box, survival, forest, heatmap, scatter and corrbar renderers are still
   in charts.js and still work; they are simply waiting on real exports.
   ========================================================================== */

